function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  const params = new URLSearchParams({ profile: input.profile === 'runtime' ? 'runtime' : 'demo', limit: String(input.limit || 100) })
  for (const symbol of input.symbols || []) params.append('symbols', String(symbol))
  for (const field of input.fields || []) params.append('fields', String(field))
  if (input.start_quarter) params.set('start_quarter', String(input.start_quarter))
  if (input.end_quarter) params.set('end_quarter', String(input.end_quarter))
  if (input.asof_date) params.set('asof_date', String(input.asof_date))
  const response = await fetch(apiOrigin() + '/api/data/fundamentals?' + params, { headers: { Accept: 'application/json' } })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}
